import numpy as np,pandas as pd
from scipy import stats
P=Path(__file__).resolve().parents[2];O=P/'outputs/round5';W=P/'work/round5';A=P/'outputs/round2_A1';R=P/'outputs/round4';sys.path.insert(0,str(A));from compute_reliability import lodo,batched_lodo,icc_sem,pair_array
SEED=20261025
def holm(p):
 p=np.asarray(p,float);order=np.argsort(p);q=np.maximum.accumulate(p[order]*np.arange(len(p),0,-1));out=np.empty_like(q);out[order]=np.minimum(q,1);return out
def booticc(g,values,pairs,boots,ids):
 lk={s:i for i,s in enumerate(g.gsm)};q=pairs[pairs.gsm1.isin(lk)&pairs.gsm2.isin(lk)];ix1=[lk[s] for s in q.gsm1];ix2=[lk[s] for s in q.gsm2];a=np.stack([values[:,ix1],values[:,ix2]],axis=2);w=boots[:,[ids.index(d) for d in q.donor]];n=w.sum(axis=1);rm=a.mean(axis=2);cm=(w[:,:,None]*a).sum(axis=1)/n[:,None];gm=cm.mean(axis=1);msr=2*(w*(rm-gm[:,None])**2).sum(axis=1)/(n-1);msc=n*((cm-gm[:,None])**2).sum(axis=1);err=a-rm[:,:,None]-cm[:,None,:]+gm[:,None,None];mse=(w[:,:,None]*err**2).sum(axis=(1,2))/(n-1);den=msr+mse+2/n*(msc-mse);return np.divide(msr-mse,den,out=np.full(len(n),np.nan),where=(n>=3)&(den>0))
def cov_adjust_nested(g,y,boots,doncov):
 ids=sorted(g.donor.unique());di=pd.Categorical(g.donor,categories=ids).codes;xa=np.c_[np.ones(len(g)),g.age.to_numpy(float)];n=np.bincount(di);w=1/n[di];ybar=np.array([y[di==j].mean() for j in range(len(ids))]);xbar=np.array([xa[di==j].mean(axis=0) for j in range(len(ids))]);xx=np.array([np.einsum('i,ij,ik->jk',w[di==j],xa[di==j],xa[di==j]) for j in range(len(ids))]);xy=np.array([xa[di==j].T@(w[di==j]*y[di==j]) for j in range(len(ids))]);c=doncov.set_index('donor').loc[ids];xc=np.c_[np.ones(len(ids)),c['cmv status'].eq('Positive').astype(float),c.Sex.eq('Male').astype(float)];m=np.asarray(boots,float);ta=np.einsum('bd,dij->bij',m,xx);tb=m@xy;aa=ta[:,None]-m[:,:,None,None]*xx;bb=tb[:,None]-m[:,:,None]*xy;ba=np.linalg.solve(aa,bb[...,None])[...,0];cc=np.einsum('di,dj->dij',xc,xc);cx=np.einsum('di,dj->dij',xc,xbar);cy=xc*ybar[:,None];gg=np.einsum('bd,dij->bij',m,cc)[:,None]-m[:,:,None,None]*cc;rhs=(m@cy)[:,None]-m[:,:,None]*cy;cross=np.einsum('bd,dij->bij',m,cx)[:,None]-m[:,:,None,None]*cx;rhs=rhs-np.einsum('bdij,bdj->bdi',cross,ba)
 try:bc=np.linalg.solve(gg,rhs[...,None])[...,0]
 except np.linalg.LinAlgError:bc=np.einsum('bdij,bdj->bdi',np.linalg.pinv(gg),rhs)
 age_res=y[None]-np.einsum('ni,bni->bn',xa,ba[:,di]);correction=np.einsum('di,bdi->bd',xc,bc);return age_res-correction[:,di]
def r2(x,y):
 b=np.linalg.lstsq(x,y,rcond=None)[0];sse=float(np.square(y-x@b).sum());sst=float(np.square(y-y.mean()).sum());v=1-sse/sst if sst else np.nan;adj=1-(1-v)*(len(y)-1)/(len(y)-np.linalg.matrix_rank(x));return v,adj,sse
def main():
 raw=pd.read_csv(R/'F2_a_e_full68_predictions.csv').rename(columns={'variant':'model'});pub=pd.read_csv(A/'main_predictions_with_LODO.csv');pub=pub[pub.clock.eq('sc-ImmuAging')].copy();pub['model']='published';allp=pd.concat([raw,pub],ignore_index=True);k=pd.read_csv(A/'provenance_inputs/K0_primary_with_released_age.csv');batch=k.set_index('gsm')['batch id'];allp['batch']=allp.gsm.map(batch);allp=allp[['model','celltype','gsm','donor','age','batch','prediction']];allp.to_csv(O/'fixed_three_model_predictions.csv',index=False);cov=pd.read_csv(O/'GEO_K0_covariate_donors.csv');assert len(cov)==68 and cov[['Sex','cmv status']].notna().all().all();ids=sorted(cov.donor);boots=np.random.default_rng(np.random.SeedSequence([SEED,4202])).multinomial(68,np.full(68,1/68),size=2000);pairs=pd.read_csv(A/'provenance_inputs/K0_primary_pair_ledger.csv');pairs=pairs[pairs.stratum.isin(['75-105d','330-400d'])];old=np.load(R/'F2_paired_ICC_bootstrap.npz');bs={};records=[];adjusted=[];explained=[];ages=[];pointrows=[]
 for (ct,model),g in allp.groupby(['celltype','model']):
  g=g.sort_values(['donor','gsm']).reset_index(drop=True);assert sorted(g.donor.unique())==ids;y=g.prediction.to_numpy();acc=lodo(g,y);bacc=batched_lodo(g,y,boots);cadj=cov_adjust_nested(g,y,np.vstack([np.ones(68,int),boots]),cov);pointadj=cadj[0];samples=cadj[1:];z=g.copy();z['age_acceleration']=acc;z['CMV_sex_adjusted_age_acceleration']=pointadj;pointrows.append(z);dm=z.groupby('donor').agg(age_acceleration=('age_acceleration','mean'),prediction=('prediction','mean'),age=('age','mean')).join(cov.set_index('donor'));yr=dm.age_acceleration.to_numpy();xc=dm['cmv status'].eq('Positive').to_numpy(float);xs=dm.Sex.eq('Male').to_numpy(float);one=np.ones(len(dm));vC,aC,sC=r2(np.c_[one,xc],yr);vS,aS,sS=r2(np.c_[one,xs],yr);vJ,aJ,sJ=r2(np.c_[one,xc,xs],yr);sst=float(np.square(yr-yr.mean()).sum());explained.append({'celltype':ct,'model':model,'n_donors':68,'CMV_R2':vC,'Sex_R2':vS,'joint_R2':vJ,'CMV_adjusted_R2':aC,'Sex_adjusted_R2':aS,'joint_adjusted_R2':aJ,'unique_CMV_R2_increment':(sS-sJ)/sst,'unique_Sex_R2_increment':(sC-sJ)/sst,'partial_CMV_R2':(sS-sJ)/sS,'partial_Sex_R2':(sC-sJ)/sC,'outcome':'one equal-weight donor mean of full68LODO age residuals','causal_interpretation':'Descriptive association only; CMV/sex can be biological age-related features.'});pr=stats.pearsonr(dm.prediction,dm.age);ages.append({'celltype':ct,'model':model,'n_donors':68,'Pearson_r':pr.statistic,'Pearson_p':pr.pvalue,'mean_error':float((dm.prediction-dm.age).mean()),'definition':'one mean predicted/chronological age per donor, full K0'})
  for st,pp in pairs.groupby('stratum'):
   q,aa=pair_array(g,acc,pp);_,ab=pair_array(g,pointadj,pp);v=booticc(g,bacc,pp,boots,ids);va=booticc(g,samples,pp,boots,ids);assert np.isfinite(v).all() and np.isfinite(va).all();bs[ct,model,st]=v
   if model in ['a','e']:assert np.allclose(v,old[f'{ct}__{model}__{st}'],rtol=0,atol=1e-11)
   lo,hi=np.percentile(v,[2.5,97.5]);la,ha=np.percentile(va,[2.5,97.5]);records.append({'celltype':ct,'model':model,'stratum':st,'n_pairs':len(q),'ICC2_1':icc_sem(aa)[0],'ICC_CI_low':lo,'ICC_CI_high':hi,'bootstrap_valid':len(v)});adjusted.append({'celltype':ct,'model':model,'stratum':st,'n_pairs':len(q),'ICC_before':icc_sem(aa)[0],'ICC_after_CMV_sex':icc_sem(ab)[0],'adjusted_ICC_CI_low':la,'adjusted_ICC_CI_high':ha,'bootstrap_valid':len(va),'method':'nested held-donor exclusion for age calibration and covariate regression; same68donors'})
  print('P1_P2',ct,model,flush=True)
 rec=pd.DataFrame(records);rec.to_csv(O/'P1_three_model_ICC_long.csv',index=False);wide=rec.pivot(index=['celltype','stratum','n_pairs'],columns='model',values=['ICC2_1','ICC_CI_low','ICC_CI_high']);wide.columns=[f'{m}__{s}' for s,m in wide.columns];wide.reset_index().to_csv(O/'P1_three_column_comparison.csv',index=False);comparison=[];multi=[]
 for ct in ['B','MONO','NK']:
  for st in ['75-105d','330-400d']:
   p=rec[rec.celltype.eq(ct)&rec.model.eq('published')&rec.stratum.eq(st)].ICC2_1.iloc[0];e=rec[rec.celltype.eq(ct)&rec.model.eq('e')&rec.stratum.eq(st)].ICC2_1.iloc[0];a=rec[rec.celltype.eq(ct)&rec.model.eq('a')&rec.stratum.eq(st)].ICC2_1.iloc[0];delta=bs[ct,'e',st]-bs[ct,'published',st];lo,hi=np.percentile(delta,[2.5,97.5]);comparison.append({'celltype':ct,'stratum':st,'ICC_published':p,'ICC_a':a,'ICC_e':e,'delta_e_minus_published':e-p,'delta_CI_low':lo,'delta_CI_high':hi,'paired_bootstrap_valid':2000});dd=bs[ct,'e',st]-bs[ct,'a',st];tail=min(1,2*min(((dd<=0).sum()+1)/2001,((dd>=0).sum()+1)/2001));centered=((abs(dd-(e-a))>=abs(e-a)).sum()+1)/2001;multi.append({'celltype':ct,'stratum':st,'delta_e_minus_a':e-a,'bootstrap_tail_p':tail,'null_centered_p_sensitivity':centered,'method_primary':'two-sided percentile-bootstrap tail probability, +1 finite-simulation correction; approximate not exact randomization p'})
 pd.DataFrame(comparison).to_csv(O/'P1_e_vs_published_paired_delta.csv',index=False);m=pd.DataFrame(multi);m['Holm6_p']=holm(m.bootstrap_tail_p);m['passes_Holm6']=m.Holm6_p.lt(.05);m['centered_Holm6_p_sensitivity']=holm(m.null_centered_p_sensitivity);m['passes_centered_Holm6_sensitivity']=m.centered_Holm6_p_sensitivity.lt(.05);m.to_csv(O/'P1_F2_Holm6.csv',index=False);pd.DataFrame(explained).to_csv(O/'P2_covariate_between_donor_R2.csv',index=False);pd.DataFrame(ages).to_csv(O/'P2_chronological_age_signal.csv',index=False);adj=pd.DataFrame(adjusted);adj.to_csv(O/'P2_CMV_sex_adjusted_ICC.csv',index=False);ret=[]
 for ct in ['B','CD4T','CD8T','MONO','NK']:
  for st in ['75-105d','330-400d']:
   q=adj[adj.celltype.eq(ct)&adj.stratum.eq(st)].set_index('model');before=q.loc['e','ICC_before']-q.loc['a','ICC_before'];after=q.loc['e','ICC_after_CMV_sex']-q.loc['a','ICC_after_CMV_sex'];ret.append({'celltype':ct,'stratum':st,'delta_e_minus_a_before':before,'delta_e_minus_a_after':after,'retained_fraction_positive_original_gain':after/before if before>0 else np.nan,'signed_ratio_supplementary':after/before if abs(before)>1e-12 else np.nan,'status':'DESCRIPTIVE_RATIO_UNCAPPED' if before>0 else 'NOT_APPLICABLE_ORIGINAL_GAIN_NOT_POSITIVE'})
 pd.DataFrame(ret).to_csv(O/'P2_retained_reliability_gain.csv',index=False);pd.concat(pointrows,ignore_index=True).to_csv(O/'P2_predictions_and_covariate_residuals.csv',index=False);np.savez_compressed(W/'P1_paired_bootstrap_ICCs.npz',**{'__'.join(k):v for k,v in bs.items()});(O/'P1_P2_status.json').write_text(json.dumps({'P1':'PASS_EXECUTED','P2':'PASS_EXECUTED_NO_PREASSERTION_OF_AGE_VALIDITY','n_donors':68,'BMI':'NOT_AVAILABLE_IN_GEO','all_original_a_e_bootstrap_arrays_recovered':True,'CMV_sex_static_and_complete':True,'primary_p_method':'percentile-bootstrap tail probability; centred-null sensitivity separately labelled','historical_F2_unchanged':True,'no_new_training':True},indent=2));print('P1_P2_COMPLETE',flush=True)
if __name__=='__main__':main()
